<?php
namespace Modules\Ran\Http\Controllers;use Illuminate\Routing\Controller;use Modules\Ran\Entities\DocumentShare;use Modules\Ran\Services\DocumentService;
class PublicShareController extends Controller{public function show(string $token,DocumentService $service){$share=$this->valid($token);$share->increment('view_count');$share->update(['last_viewed_at'=>now()]);$document=$service->find($share->document_type,$share->document_id);$template=$service->template($share->document_type,null,(int)$share->business_id);$type=$share->document_type;$sections=$share->selected_sections;return view('ran::documents.public',compact('share','document','template','type','sections'));}public function download(string $token,DocumentService $service){$share=$this->valid($token);$share->increment('download_count');$document=$service->find($share->document_type,$share->document_id);$template=$service->template($share->document_type,null,(int)$share->business_id);$type=$share->document_type;$sections=$share->selected_sections;$html=view('ran::documents.public',compact('share','document','template','type','sections'))->render();return response($html,200,['Content-Type'=>'text/html; charset=UTF-8','Content-Disposition'=>'attachment; filename="ran-document-'.$share->id.'.html"']);}private function valid(string $token):DocumentShare{$s=DocumentShare::withoutGlobalScopes()->where('token',$token)->where('is_active',1)->firstOrFail();abort_if($s->expires_at&&$s->expires_at->isPast(),410,'This Ran document link has expired.');return $s;}}
